CREATE TABLE public.assessment_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid, question_id uuid, sort_order integer, points numeric, created_at timestamp with time zone);
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text, target_type text, target_id uuid, metadata jsonb, created_at timestamp with time zone);
CREATE TABLE public.curriculum_tracks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), track_name text, track_code text, description text, is_active boolean, created_at timestamp with time zone);
CREATE TABLE public.grades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text, name text, category text, sort_order integer, created_at timestamp with time zone, curriculum_track_id uuid);
CREATE TABLE public.lesson_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, title text, instructions text, sort_order integer, created_at timestamp with time zone, assessment_code text);
CREATE TABLE public.lesson_book_contents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, content text, pdf_url text, created_at timestamp with time zone, updated_at timestamp with time zone);
CREATE TABLE public.lesson_capability_lifecycle (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, capability text, status text, ready_snapshot jsonb, ready_hash text, draft_hash text, draft_updated_at timestamp with time zone, reviewed_by uuid, reviewed_at timestamp with time zone, ready_by uuid, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone);
CREATE TABLE public.lesson_explanations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, title text, content text, sort_order integer, created_at timestamp with time zone, updated_at timestamp with time zone, explanation_code text);
CREATE TABLE public.lesson_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, resource_type text, title text, url text, description text, sort_order integer, created_at timestamp with time zone, resource_code text, html_resource_type text, metadata jsonb, is_primary boolean);
CREATE TABLE public.lesson_simulations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, title text, description text, phet_url text, thumbnail_url text, sort_order integer, created_at timestamp with time zone);
CREATE TABLE public.lesson_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, summary text, key_points jsonb, study_tip text, created_at timestamp with time zone, updated_at timestamp with time zone);
CREATE TABLE public.lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid, slug text, title text, duration text, video_url text, content_text text, content_pdf_url text, is_free boolean, sort_order integer, created_at timestamp with time zone, updated_at timestamp with time zone, semester integer, unit_id uuid, has_video boolean, has_content_pdf boolean, delivery_mode text);
CREATE TABLE public.practice_attempt_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), practice_attempt_id uuid, question_revision_id uuid, logical_question_id uuid, question_order integer, rendered_question_text text, rendered_stimulus_text text, rendered_options jsonb, option_order_mapping jsonb, max_score numeric, payload_hash text, payload_hash_version text, created_at timestamp with time zone);
CREATE TABLE public.practice_attempt_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), practice_attempt_id uuid, practice_attempt_question_id uuid, selected_option_code text, response_text text, response_payload jsonb, requires_manual_review boolean, grading_status text, auto_score numeric, manual_score numeric, final_score numeric, max_score numeric, submitted_at timestamp with time zone, graded_at timestamp with time zone, finalized_at timestamp with time zone, created_at timestamp with time zone);
CREATE TABLE public.practice_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, attempt_type text, lesson_assessment_id uuid, unit_id uuid, started_at timestamp with time zone, submitted_at timestamp with time zone, grading_status text, total_score numeric, max_score numeric, attempt_pin_mode text);
CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, full_name text, phone text, grade_id text, avatar_url text, created_at timestamp with time zone, updated_at timestamp with time zone, referral_code text, referred_by text, governorate text, school_name text, parent_email text, parent_phone text, governorate_id uuid, grade_uuid uuid, curriculum_track_id uuid);
CREATE TABLE public.question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_revision_id uuid, option_code text, body text, sort_order integer, is_correct boolean, created_at timestamp with time zone);
CREATE TABLE public.question_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid, revision_number integer, status text, interaction_type text, grading_mode text, educational_label text, question_text text, stimulus_text text, max_score numeric, allow_partial boolean, requires_media boolean, manual_grading_required boolean, payload_hash text, payload_hash_version text, source_payload_hash text, backfill_version text, created_at timestamp with time zone, created_by uuid, reviewed_at timestamp with time zone, reviewed_by uuid, published_at timestamp with time zone, published_by uuid, superseded_at timestamp with time zone, rejected_at timestamp with time zone, rejected_by uuid, rejection_reason text);
CREATE TABLE public.questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid, subject_id uuid, question_text text, options jsonb, correct_index integer, explanation text, question_type text, year integer, sort_order integer, created_at timestamp with time zone, unit text, semester integer, code text, created_by uuid, archived_at timestamp with time zone, archived_by uuid, current_published_revision_id uuid);
CREATE TABLE public.subject_curriculum_tracks (subject_id uuid, curriculum_track_id uuid, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, created_by uuid);
CREATE TABLE public.subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grade_id uuid, slug text, name text, icon text, color text, lessons_count integer, sort_order integer, created_at timestamp with time zone, semester integer, curriculum_track_id uuid, code text, group_code text, group_name text);
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, role text);
CREATE TABLE public.subject_textbooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid, curriculum_track_id uuid, semester smallint, title text, storage_bucket text, storage_path text, file_name text, file_size bigint, version text, sha256 text, sort_order integer, is_active boolean, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, coverage_type text, book_type text);
